// ─── Helper: WhatsApp link ───────────────────────────────────────────────────
export function waLink(productName, amount = null) {
  const phone = '221774728991'
  const text = amount
    ? `Bonjour ABAWI, je souhaite commander *${productName}* pour *${amount.toLocaleString('fr-FR')} F CFA*.`
    : `Bonjour ABAWI, je souhaite commander *${productName}*.`
  return `https://wa.me/${phone}?text=${encodeURIComponent(text)}`
}

