// ─── Summary matcher ─────────────────────────────────────────────────────────
const STOP_WORDS = new Set(['le','la','les','un','une','des','de','du','et','a','au','aux','en','dans','sur','avec','pour','par','sans','sous','vers','entre','chez','devant','derriere','durant','pendant','apres','avant','depuis','jusque','que','qui','quoi','dont','ou','mais','donc','or','ni','car','si','l','d','s','n','c','j','t','y','m','ce','cet','cette','ces','mon','ma','mes','ton','ta','tes','son','sa','ses','notre','nos','votre','vos','leur','leurs','se','aussi','alors','ainsi','puis','ensuite','enfin','bien','mal','plus','moins','tres','trop','assez','peu','beaucoup','tout','tous','toute','toutes','autre','autres','meme','seul','plusieurs','certains','certaines','chaque','aucun','aucune','tel','telle','tels','telles','divers','diverses','quasi','presque','plutot','davantage','tant','tellement','autant','si','vite','lentement','facilement','difficilement','librement','facile','difficile','possible','impossible','probable','necessaire','inutile','utile','exprès','juste','droit','faux','vrai','vraiment','reellement','effectivement','notamment','surtout','particulierement','principalement','generalement','normalement','habituellement','ordinairement','couramment','frequemment','rarement','parfois','souvent','toujours','jamais','deja','encore','maintenant','aujourdhui','hier','demain','bientot','tot','tard','longtemps','autrefois','jadis','auparavant','anterieurement','prealablement','ulterieurement','aussitot','sitot','immediatement','instantanement','soudain','subitement','brusquement','progressivement','graduellement','approximativement','environ','grosso','modo'])

function normalizeWords(str) {
  return slugify(str).split('-').filter(w => w.length > 1 && !STOP_WORDS.has(w))
}

export function findSummaryForContent(titre) {
  const contentWords = normalizeWords(titre)
  if (!contentWords.length) return null
  for (const s of summaries) {
    const sumWords = normalizeWords(s.titre)
    const common = contentWords.filter(w => sumWords.includes(w))
    if (common.length >= 2) return s
    const cSlug = slugify(titre)
    const sSlug = slugify(s.titre)
    if (cSlug.includes(sSlug) || sSlug.includes(cSlug)) return s
  }
  return null
}
